24	/**
25	 * Small stateless helpers for the SHA-256 hex derivations that back the application's
26	 * identity values (customer codes, household ids).
27	 *
28	 * <p>Keeping the derivation in one place means every identity value built from a truncated
29	 * hex digest reads the same computation and they can never drift apart.
30	 */
31	public abstract class HashUtils {
32	
33	    /**
34	     * The full, lower-case hex encoding of the SHA-256 digest of the UTF-8 bytes of
35	     * {@code source} (64 hex characters).
36	     *
37	     * @param source the string to digest
38	     * @return the 64-character lower-case hex SHA-256 digest of {@code source}
39	     */
40	    public static String sha256Hex(String source) {
41	        try {
42	            byte[] digest = MessageDigest.getInstance("SHA-256")
43	                .digest(source.getBytes(StandardCharsets.UTF_8));
44	            StringBuilder sb = new StringBuilder(digest.length * 2);
45	            for (byte b : digest) {
46	                sb.append(String.format("%02x", b));
47	            }
48	            return sb.toString();
49	        }
50	        catch (NoSuchAlgorithmException e) {
51	            throw new IllegalStateException("SHA-256 not available", e);
52	        }
53	    }
54	
55	    /**
56	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
57	     * bytes of {@code source}.
58	     *
59	     * @param source the string to digest
60	     * @param length the number of leading hex characters to return
61	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
62	     */
63	    public static String sha256HexPrefix(String source, int length) {
64	        return sha256Hex(source).substring(0, length).toUpperCase(Locale.ROOT);
65	    }
66	}
